"""Apply the exact four-path native-control candidate in an Actions checkout.

Compressed transport only. CI retains the decoded diff and complete source
receipt. This script does not execute Godot or grant gameplay authority.
"""
from __future__ import annotations

import base64
import hashlib
from pathlib import Path
import subprocess
import sys
import zlib

BASE = "09addba8b544e21753846f2002880a7826b85f31"
PATCH_SHA256 = "08f366e53915a6c6e71b1ee74b3ba00ef536ac722ac51bcba3058943b3de6af5"
EXPECTED = {
    "scripts/narrative/DialogicRuntimeAdapter.gd": "d2807bf4df6a018efb8776464433f81b5727be3e",
    "tests/fixtures/dialogic/scene_playable_native.dtl": "12f4043df0e4a8a42524a47c6f6a0b93e6dd964e",
    "tests/integration/test_scene_playable_native_control.gd": "c4c2c9e1d3db00edba8aa789ece32c2da4f2e943",
    "tests/integration/test_scene_playable_native_control.gd.uid": "c7c99d96f87851c9ef027e99343f4ef4e252edbc",
}
PATCH = """"""


def main() -> None:
    if len(sys.argv) != 2:
        raise SystemExit("usage: patch_scene_playable_native.py CHECKOUT")
    root = Path(sys.argv[1]).resolve()
    def git(*args: str, data: bytes | None = None) -> bytes:
        return subprocess.run(["git", "-C", str(root), *args], input=data,
                              check=True, stdout=subprocess.PIPE).stdout
    if git("rev-parse", "HEAD").decode().strip() != BASE:
        raise SystemExit("unexpected source parent")
    if git("status", "--porcelain").strip():
        raise SystemExit("source checkout is not clean")
    if git("rev-parse", "HEAD:scripts/narrative/DialogicRuntimeAdapter.gd").decode().strip() != "1e511b1238b51fc15bdee79ca083b0f0b8105573":
        raise SystemExit("native owner baseline differs")
    for path in list(EXPECTED)[1:]:
        if (root / path).exists():
            raise SystemExit(f"new fixture path already exists: {path}")
    patch = zlib.decompress(base64.b64decode(PATCH, validate=True))
    if hashlib.sha256(patch).hexdigest() != PATCH_SHA256:
        raise SystemExit("transport patch digest mismatch")
    git("apply", "--check", "-", data=patch)
    git("apply", "-", data=patch)
    for path, expected in EXPECTED.items():
        if git("hash-object", "--", path).decode().strip() != expected:
            raise SystemExit(f"candidate blob differs: {path}")
    print("EXACT_NATIVE_PATCH_APPLIED: four source paths; engine NOT RUN")


if __name__ == "__main__":
    main()
